function pooledRain(heights: number[][]): number {
  const m = heights.length, n = heights[0].length;
  const lvl = heights.map((row, i) => row.map((h, j) => (i === 0 || j === 0 || i === m - 1 || j === n - 1 ? h : Infinity)));
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 1; i < m - 1; i++) for (let j = 1; j < n - 1; j++) {
      const v = Math.max(heights[i][j], Math.min(lvl[i - 1][j], lvl[i + 1][j], lvl[i][j - 1], lvl[i][j + 1]));
      if (v < lvl[i][j]) { lvl[i][j] = v; changed = true; }
    }
  }
  let total = 0;
  for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) total += lvl[i][j] - heights[i][j];
  return total;
}

