function pooledRain(heights: number[][]): number {
  const m = heights.length, n = heights[0].length;
  const seen = heights.map(row => row.map(() => false));
  // min-heap of [level, i, j]
  const h: number[][] = [];
  const push = (e: number[]) => {
    h.push(e);
    let i = h.length - 1;
    while (i > 0) { const p = (i - 1) >> 1; if (h[p][0] <= h[i][0]) break; [h[p], h[i]] = [h[i], h[p]]; i = p; }
  };
  const pop = () => {
    const top = h[0], last = h.pop()!;
    if (h.length) {
      h[0] = last;
      let i = 0;
      for (;;) {
        let s = i; const l = 2 * i + 1, r = l + 1;
        if (l < h.length && h[l][0] < h[s][0]) s = l;
        if (r < h.length && h[r][0] < h[s][0]) s = r;
        if (s === i) break;
        [h[s], h[i]] = [h[i], h[s]]; i = s;
      }
    }
    return top;
  };
  for (let i = 0; i < m; i++) for (let j = 0; j < n; j++)
    if (i === 0 || j === 0 || i === m - 1 || j === n - 1) { seen[i][j] = true; push([heights[i][j], i, j]); }
  let total = 0;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  while (h.length) {
    const [lvl, i, j] = pop();
    for (const [di, dj] of dirs) {
      const a = i + di, b = j + dj;
      if (a < 0 || b < 0 || a >= m || b >= n || seen[a][b]) continue;
      seen[a][b] = true;
      total += Math.max(0, lvl - heights[a][b]);
      push([Math.max(lvl, heights[a][b]), a, b]);
    }
  }
  return total;
}

