                    heap.append((heights[i][j], i, j))
        heapq.heapify(heap)
        total = 0
        while heap:
            lvl, i, j = heapq.heappop(heap)
            for a, b in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if 0 <= a < m and 0 <= b < n and not seen[a][b]:
                    seen[a][b] = True
                    total += max(0, lvl - heights[a][b])
                    heapq.heappush(heap, (max(lvl, heights[a][b]), a, b))
        return total

